CREATE TABLE "loan_requests" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "loan_requests_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"employee_id" bigint NOT NULL,
	"principal_amount" numeric(12, 2) NOT NULL,
	"installment_count" smallint NOT NULL,
	"reason" text NOT NULL,
	"status" "loan_request_status" DEFAULT 'pending' NOT NULL,
	"requested_by_user_account_id" bigint NOT NULL,
	"requested_at" timestamp with time zone DEFAULT now() NOT NULL,
	"decided_by_user_account_id" bigint,
	"decided_at" timestamp with time zone,
	"decision_note" text,
	"loan_id" bigint,
	CONSTRAINT "chk_loan_request_principal_positive" CHECK ("loan_requests"."principal_amount" > 0),
	CONSTRAINT "chk_loan_request_installment_count" CHECK ("loan_requests"."installment_count" between 1 and 5),
	CONSTRAINT "chk_loan_request_reason" CHECK (length(trim("loan_requests"."reason")) > 0),
	CONSTRAINT "chk_loan_request_decision" CHECK ((
    ("loan_requests"."status" = 'pending' and "loan_requests"."decided_by_user_account_id" is null and "loan_requests"."decided_at" is null and "loan_requests"."decision_note" is null and "loan_requests"."loan_id" is null)
    or ("loan_requests"."status" = 'approved' and "loan_requests"."decided_by_user_account_id" is not null and "loan_requests"."decided_at" is not null and "loan_requests"."loan_id" is not null)
    or ("loan_requests"."status" = 'rejected' and "loan_requests"."decided_by_user_account_id" is not null and "loan_requests"."decided_at" is not null and "loan_requests"."loan_id" is null and length(trim("loan_requests"."decision_note")) > 0 and "loan_requests"."decision_note" is not null)
  ))
);
